      "verdict": "true_drift",
      "reason": "The published top-level `httpx.get()` signature has no `extensions` parameter, so the documented call cannot be used as written.",
      "code_citation": {
        "path": "httpx/_api.py",
        "start_line": 174,
        "end_line": 186,
        "quote": "def get(\n    url: URL | str,\n    *,\n    params: QueryParamTypes | None = None,\n    headers: HeaderTypes | None = None,\n    cookies: CookieTypes | None = None,\n    auth: AuthTypes | None = None,\n    proxy: ProxyTypes | None = None,\n    follow_redirects: bool = False,\n    verify: ssl.SSLContext | str | bool = True,\n    timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n    trust_env: bool = True,\n) -> Response:"
      },
      "suggested_doc_fix": "Use a Client instance for extension support, e.g. `client = httpx.Client(); response = client.get(\"https://www.example.com\", extensions=extensions)`."
    }
  ],
  "additional_findings": [
    {
      "finding_id": "AD-1",
      "drift_kind": "signature",
      "explanation": "The top-level `httpx.request()` signature also lacks an `extensions` parameter, so the documented `httpx.request(..., extensions=extensions)` call is invalid in the same way as the candidate.",
